function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let z;
try { z = require("zod").z; } catch (e) { broken("cannot load zod: " + e.message); }
const schema = z.cuid();
if (!schema.safeParse("cjld2cjxh0000qzrmn831i7rn").success) broken("a 25-character CUID v1 was rejected");
if (schema.safeParse("dabcdef").success) broken("a string not starting with c was accepted");
if (schema.safeParse("cabcde").success) broken("a 6-character string was accepted");
const short = "cabcdef";
if (!schema.safeParse(short).success) symptom("z.cuid() rejects the 7-character string " + short);
console.log("OK: z.cuid() accepts the 7-character string " + short);

